export function lruCache(capacity        , operations                     )                  {
const cache=new Map               (),out                =[];for(const op of operations){const key=op[1]          ;if(op[0]==="get"){const v=cache.get(key);out.push(v??-1);if(v!==undefined){cache.delete(key);cache.set(key,v);}}else{cache.delete(key);cache.set(key,op[2]          );if(cache.size>capacity)cache.delete(cache.keys().next().value );out.push(null);}}return out;
}

