export function lruCache(capacity: number, operations: (string|number)[][]): (number|null)[] {
const cache=new Map<number,number>(),out:(number|null)[]=[];for(const op of operations){const key=op[1] as number;if(op[0]==="get"){const v=cache.get(key);out.push(v??-1);if(v!==undefined){cache.delete(key);cache.set(key,v);}}else{cache.delete(key);cache.set(key,op[2] as number);if(cache.size>capacity)cache.delete(cache.keys().next().value!);out.push(null);}}return out;
}
